node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find user Maya Chen with zip 94110
const users = db.prepare(\"SELECT user_id, name, email, address_json, skill_ids_json FROM users WHERE skill_ids_json LIKE '%tau2Retail%' AND LOWER(name) LIKE '%maya%chen%'\").all();

if (users.length === 0) {
  console.log('User not found');
  process.exit(0);
}

const user = users[0];
const address = JSON.parse(user.address_json || '{}');

// Check zip
if (address.zip !== '94110') {
  console.log('User found but zip does not match 94110');
  process.exit(0);
}

console.log('=== Customer Profile ===');
console.log('User ID:', user.user_id);
console.log('Name:', user.name);
console.log('Email:', user.email);
console.log('Address:', JSON.stringify(address, null, 2));

// Payment methods
const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id=?').all(user.user_id);
console.log('\nPayment Methods:');
pms.forEach(pm => console.log(JSON.stringify(pm)));

// Orders
const orders = db.prepare(\"SELECT order_id, status FROM orders WHERE source_skill='tau2Retail' AND customer_id=?\").all(user.user_id);
console.log('\nOrders:');
orders.forEach(o => console.log(o.order_id, '-', o.status));
"

